338	     * source of truth for the fiscal year, so {@link #getFiscalYear()}, the
339	     * {@link #getMembershipNumber() membership number} year segment and the tenure count
340	     * in {@link #getMembershipPoints()} cannot drift apart.
341	     */
342	    private static int fiscalYearOf(LocalDate date) {
343	        int year = date.getYear();
344	        return date.getMonthValue() >= Month.JULY.getValue() ? year : year - 1;
345	    }
