388	        int sum = 0;
389	        boolean dbl = true;
390	        for (int i = this.customerCode.length() - 1; i >= 0; i--) {
391	            char c = this.customerCode.charAt(i);
392	            if (c < '0' || c > '9') {
393	                continue;
394	            }
395	            int d = c - '0';
396	            if (dbl) {
397	                d *= 2;
398	                if (d > 9) {
399	                    d -= 9;
400	                }
401	            }
402	            sum += d;
403	            dbl = !dbl;
404	        }
405	        return (10 - (sum % 10)) % 10;
406	    }
407	
408	    /**
409	     * The owner's membership points: a running score built from the owner's own fields.
410	     * Starts at 0 and gains 2 when an email address is present, a further 1 when the owner
411	     * has no namesakes ({@code namesakeCount} is 0), a further 2 when it belongs to a
412	     * household of 3 or more members ({@code householdSize} is 3 or more), and a further 3
413	     * for tenure of more than one elapsed fiscal year (the fiscal years, starting 1 July,
414	     * from {@link #registrationDate} to the current date). A newly created owner has zero
415	     * tenure, so the pre-tenure factors alone top out at 5 points. Derived from the owner's
416	     * own fields.
417	     */
418	    @Transient
419	    public Integer getMembershipPoints() {
420	        int points = 0;
421	        boolean hasEmail = this.email != null && !this.email.isBlank();
422	        if (hasEmail) {
423	            points += 2;
424	        }
425	        boolean unique = this.namesakeCount != null && this.namesakeCount == 0;
426	        if (unique) {
427	            points += 1;
428	        }
429	        boolean largeHousehold = this.householdSize != null && this.householdSize >= 3;
430	        if (largeHousehold) {
431	            points += 2;
432	        }
433	        boolean tenured = this.registrationDate != null
434	            && (fiscalYearOf(LocalDate.now()) - fiscalYearOf(this.registrationDate)) > 1;
435	        if (tenured) {
436	            points += 3;
437	        }
438	        return points;
439	    }
440	
441	    /**
442	     * The owner's membership level: a number from 1 to 4 derived by banding
443	     * {@link #getMembershipPoints()} — 1 for 0-1 points, 2 for 2-3, 3 for 4-5 and 4 for 6
444	     * or more. Derived from the owner's own fields, then capped by
445	     * {@link #membershipLevelCap} when set: a new owner's level cannot exceed one above the
446	     * current maximum level among their household members. With no existing household member
447	     * the cap is absent and the banded value stands.
448	     */
449	    @Transient
450	    public Integer getMembershipLevel() {
451	        int level = bandMembershipLevel(getMembershipPoints());
452	        if (this.membershipLevelCap != null && this.membershipLevelCap < level) {
453	            return this.membershipLevelCap;
454	        }
455	        return level;
456	    }
457	
458	    private static int bandMembershipLevel(int points) {
459	        if (points <= 1) {
460	            return 1;
461	        }
462	        if (points <= 3) {
463	            return 2;
464	        }
465	        if (points <= 5) {
466	            return 3;
467	        }
468	        return 4;
469	    }
470	
471	    /**
472	     * Fixed city-to-region lookup table. Any city not listed derives locality
473	     * {@code "UNKNOWN"}.
474	     */
475	    private static final Map<String, String> CITY_REGION = Map.of(
476	        "Sydney", "NSW",
477	        "Melbourne", "VIC",
478	        "Brisbane", "QLD");
479	
480	    /**
481	     * Region -> inclusive 4-digit postcode range {low, high}: NSW 2000-2099,
482	     * VIC 3000-3099, QLD 4000-4099. The single source of truth for the
483	     * postcode-to-region mapping, consulted by {@link #regionForPostcode(String)}
484	     * (used by locality derivation) and {@link #hasPostcodeRange(String)} (used by
485	     * postcode validation).
486	     */
487	    private static final Map<String, int[]> REGION_POSTCODE_RANGES = Map.of(
488	        "NSW", new int[] {2000, 2099},
489	        "VIC", new int[] {3000, 3099},
490	        "QLD", new int[] {4000, 4099});
491	
492	    /**
493	     * Fixed region-to-timezone lookup table, mapping each region to its IANA timezone
494	     * name: NSW->Australia/Sydney, VIC->Australia/Melbourne, QLD->Australia/Brisbane.
495	     * Any region not listed (including {@code "UNKNOWN"}) has no timezone.
496	     */
497	    private static final Map<String, String> REGION_TIMEZONE = Map.of(
498	        "NSW", "Australia/Sydney",
499	        "VIC", "Australia/Melbourne",
500	        "QLD", "Australia/Brisbane");
501	
502	    /**
503	     * The owner's locality: the REGION component of the owner's region-and-hash identity.
504	     * Read off the {@code customerCode} prefix (the part before the first {@code '-'}) when
505	     * a customer code is present, otherwise derived straight from the postcode via
506	     * {@link #identityRegion(String)}. Either way this yields the region the customer code
507	     * was built from — NSW/VIC/QLD, or {@code "UNKNOWN"} when the postcode is absent or in
508	     * no known range. Derived from the owner's own fields.
509	     */
510	    @Transient
511	    public String getLocality() {
512	        if (this.customerCode != null) {
513	            int dash = this.customerCode.indexOf('-');
514	            if (dash > 0) {
515	                return this.customerCode.substring(0, dash);
516	            }
517	        }
518	        return identityRegion(this.postcode);
519	    }
520	
521	    /**
522	     * The REGION component of an owner's region-and-hash identity: the region derived from
523	     * the postcode via {@link #regionForPostcode(String)} (NSW/VIC/QLD), or
524	     * {@code "UNKNOWN"} when the postcode is absent or in no known range. The single source
525	     * of truth for the identity's region, so the {@code customerCode} prefix and the
526	     * {@link #getLocality() locality} cannot drift apart.
527	     */
528	    public static String identityRegion(String postcode) {
529	        String region = regionForPostcode(postcode);
530	        return region != null ? region : "UNKNOWN";
531	    }
532	
533	    /**
534	     * The canonical region for a city per the fixed city-to-region table
535	     * ({@code Sydney->NSW}, {@code Melbourne->VIC}, {@code Brisbane->QLD}), or
536	     * {@code "UNKNOWN"} when the city is not in the table. The single source of truth
537	     * for the city-to-region mapping, used as the city's region in postcode validation.
538	     */
539	    public static String regionForCity(String city) {
540	        return CITY_REGION.getOrDefault(city, "UNKNOWN");
541	    }
542	
543	    /**
544	     * The canonical region for a 4-digit postcode per the fixed range table
545	     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099), or {@code null} when the postcode
546	     * is absent, not a well-formed integer, or in no known range. Reads the shared
547	     * {@link #REGION_POSTCODE_RANGES} table; used by {@link #identityRegion(String)}
548	     * for the identity's region and by postcode validation to range-check a submitted
549	     * postcode against its city's region.
550	     */
551	    public static String regionForPostcode(String postcode) {
552	        if (postcode == null) {
553	            return null;
554	        }
555	        int value;
556	        try {
557	            value = Integer.parseInt(postcode.trim());
558	        } catch (NumberFormatException ex) {
559	            return null;
560	        }
561	        for (Map.Entry<String, int[]> entry : REGION_POSTCODE_RANGES.entrySet()) {
562	            int[] range = entry.getValue();
563	            if (value >= range[0] && value <= range[1]) {
564	                return entry.getKey();
565	            }
566	        }
567	        return null;
568	    }
569	
570	    /**
571	     * Whether the region is subject to postcode range validation, i.e. has a known
572	     * range in the shared {@link #REGION_POSTCODE_RANGES} table. A region with no range
573	     * (including {@code "UNKNOWN"}) accepts any well-formed postcode.
574	     */
575	    public static boolean hasPostcodeRange(String region) {
576	        return REGION_POSTCODE_RANGES.containsKey(region);
577	    }
578	
579	    /**
580	     * The owner's IANA timezone, derived from the owner's {@link #getLocality() locality}
581	     * (its region) via the fixed region-to-timezone table ({@code NSW->Australia/Sydney},
582	     * {@code VIC->Australia/Melbourne}, {@code QLD->Australia/Brisbane}). Null when the
583	     * region is not one of these (e.g. {@code "UNKNOWN"}). Derived from the owner's own
584	     * fields.
585	     */
586	    @Transient
587	    public String getTimezone() {
588	        return REGION_TIMEZONE.get(getLocality());
589	    }
590	
591	    /**
592	     * The owner's preferred contact channel: {@code "EMAIL"} when an email address is
593	     * present, otherwise {@code "PHONE"}. Derived from the owner's own fields.
594	     */
595	    @Transient
596	    public String getContactPreference() {
597	        boolean hasEmail = this.email != null && !this.email.isBlank();
598	        return hasEmail ? "EMAIL" : "PHONE";
599	    }
600	
601	    /**
602	     * The owner's identity key: the lower-case hex SHA-256 of
603	     * {@code normalizedTelephone + "|" + lowerEmail + "|" + soundex(lastName)}. The
604	     * telephone is already stored in E.164 form, the email is lower-cased (an empty segment
605	     * when absent), and the last name is reduced to its {@link #soundex(String) Soundex}
606	     * code. This is the single identity used for duplicate detection: two owners with the
607	     * same key are the same person (a 409 on create); an owner whose key differs but whose
608	     * Soundex last name and postcode match an existing owner is a soft match instead.
609	     * Derived from the owner's own fields.
610	     */
611	    @Transient
612	    public String getIdentityKey() {
613	        String normalizedTelephone = keyPart(this.telephone);
614	        String lowerEmail = keyPart(this.email == null ? null : this.email.toLowerCase(Locale.ROOT));
615	        String soundexLastName = soundex(this.getLastName());
616	        return sha256Hex(normalizedTelephone + "|" + lowerEmail + "|" + soundexLastName);
617	    }
618	
619	    private static String keyPart(String value) {
620	        return (value == null || value.isBlank()) ? "" : value;
621	    }
622	
623	    /** Lower-case hex SHA-256 of the UTF-8 bytes of {@code value}. */
624	    private static String sha256Hex(String value) {
625	        try {
626	            byte[] digest = MessageDigest.getInstance("SHA-256")
627	                .digest(value.getBytes(StandardCharsets.UTF_8));
628	            StringBuilder sb = new StringBuilder(digest.length * 2);
629	            for (byte b : digest) {
630	                sb.append(String.format("%02x", b));
631	            }
632	            return sb.toString();
633	        }
634	        catch (NoSuchAlgorithmException ex) {
635	            throw new IllegalStateException("SHA-256 not available", ex);
636	        }
637	    }
638	
639	    /**
640	     * The American Soundex code of {@code name}: the upper-cased first letter followed by
641	     * three digits that encode the remaining consonants. Vowels and {@code H}/{@code W} are
642	     * not coded; adjacent letters with the same code collapse to one, as do two same-coded
643	     * letters separated only by {@code H} or {@code W}. The code is right-padded with zeros
644	     * and truncated to four characters. An absent or letter-free name yields the empty
645	     * string. The single source of truth for an owner's last-name phonetic key, used by the
646	     * {@link #getIdentityKey() identity key} and by soft-duplicate matching. It lives here
647	     * (rather than beside the exact-match name normalization in the package-private
648	     * {@code OwnerNames} helper) because {@code getIdentityKey()} is an entity-level derived
649	     * getter and must not depend on the request-function layer; the two are distinct name
650	     * concerns — exact comparison vs. phonetic keying — not a duplicated utility.
651	     */
652	    public static String soundex(String name) {
653	        if (name == null) {
654	            return "";
655	        }
656	        String letters = name.toUpperCase(Locale.ROOT).replaceAll("[^A-Z]", "");
657	        if (letters.isEmpty()) {
658	            return "";
659	        }
660	        StringBuilder code = new StringBuilder();
661	        code.append(letters.charAt(0));
662	        char prev = soundexDigit(letters.charAt(0));
663	        for (int i = 1; i < letters.length() && code.length() < 4; i++) {
664	            char c = letters.charAt(i);
665	            char digit = soundexDigit(c);
666	            if (digit != '0' && digit != prev) {
667	                code.append(digit);
668	            }
669	            // Vowels reset the previous code so same-coded consonants either side are coded
670	            // twice; H and W do not, so same-coded letters they separate still collapse.
671	            if (c != 'H' && c != 'W') {
672	                prev = digit;
673	            }
674	        }
675	        while (code.length() < 4) {
676	            code.append('0');
677	        }
678	        return code.toString();
679	    }
680	
681	    private static char soundexDigit(char c) {
682	        switch (c) {
683	            case 'B': case 'F': case 'P': case 'V':
684	                return '1';
685	            case 'C': case 'G': case 'J': case 'K': case 'Q': case 'S': case 'X': case 'Z':
686	                return '2';
687	            case 'D': case 'T':
688	                return '3';
689	            case 'L':
690	                return '4';
691	            case 'M': case 'N':
692	                return '5';
693	            case 'R':
694	                return '6';
695	            default:
696	                return '0';
697	        }
698	    }
699	
700	    /**
701	     * The stored E.164 {@link #telephone} formatted for humans: the country code,
702	     * a space, then the national digits grouped in threes (e.g.
703	     * {@code "+61 412 345 678"}). The {@code '+'} and country code are taken from the
704	     * E.164 value (a {@code '+1'} NANP country code is a single digit, any other is
705	     * treated as two digits, matching the recognized {@code '+61'}/{@code '+1'} forms),
706	     * and the national digits follow in space-separated groups of three. Returns the raw
707	     * value unchanged when it is absent or not a {@code '+'}-prefixed run of digits.
708	     * Derived from the owner's own fields; the raw {@link #telephone} stays E.164.
709	     */
710	    @Transient
711	    public String getTelephoneDisplay() {
712	        if (this.telephone == null || !this.telephone.startsWith("+")) {
713	            return this.telephone;
714	        }
715	        String digits = this.telephone.substring(1);
716	        if (!digits.matches("\\d+")) {
717	            return this.telephone;
718	        }
719	        int countryCodeLength = digits.startsWith("1") ? 1 : 2;
720	        if (digits.length() <= countryCodeLength) {
721	            return this.telephone;
722	        }
723	        String countryCode = digits.substring(0, countryCodeLength);
724	        String national = digits.substring(countryCodeLength);
725	        StringBuilder grouped = new StringBuilder();
726	        for (int i = 0; i < national.length(); i += 3) {
727	            if (grouped.length() > 0) {
728	                grouped.append(' ');
729	            }
730	            grouped.append(national, i, Math.min(i + 3, national.length()));
731	        }
732	        return "+" + countryCode + " " + grouped;
733	    }
734	
735	    protected Set<Pet> getPetsInternal() {
736	        if (this.pets == null) {
737	            this.pets = new HashSet<>();
738	        }
739	        return this.pets;
740	    }
741	
742	    protected void setPetsInternal(Set<Pet> pets) {
743	        this.pets = pets;
744	    }
745	
746	    public List<Pet> getPets() {
747	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
748	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
749	        return Collections.unmodifiableList(sortedPets);
750	    }
751	
752	    public void setPets(List<Pet> pets) {
753	        this.pets = new HashSet<>(pets);
754	    }
755	
756	    public void addPet(Pet pet) {
757	        getPetsInternal().add(pet);
758	        pet.setOwner(this);
759	    }
760	
761	    /**
762	     * Return the Pet with the given name, or null if none found for this Owner.
763	     *
764	     * @param name to test
765	     * @return true if pet name is already in use
766	     */
767	    public Pet getPet(String name) {
768	        return getPet(name, false);
769	    }
770	
771	    /**
772	     * Return the Pet with the given name, or null if none found for this Owner.
773	     *
774	     * @param name to test
775	     * @return true if pet name is already in use
776	     */
777	    public Pet getPet(String name, boolean ignoreNew) {
778	        name = name.toLowerCase();
779	        for (Pet pet : getPetsInternal()) {
780	            if (!ignoreNew || !pet.isNew()) {
781	                String compName = pet.getName();
782	                compName = compName.toLowerCase();
783	                if (compName.equals(name)) {
784	                    return pet;
785	                }
786	            }
787	        }
788	        return null;
789	    }
790	
791	    public Pet getPet(Integer petId) {
792	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
793	    }
794	
795	    @Override
796	    public String toString() {
797	        return new ToStringCreator(this)
798	
799	            .append("id", this.getId())
800	            .append("new", this.isNew())
801	            .append("lastName", this.getLastName())
802	            .append("firstName", this.getFirstName())
803	            .append("address", this.address)
804	            .append("city", this.city)
805	            .append("telephone", this.telephone)
806	            .append("email", this.email)
807	            .toString();
808	    }
809	}
